'use strict';

/* Sprites pintados das torres, embutidos como data URI.
 *
 * Para cada torre, os quadros foram recortados na MESMA janela centrada no
 * disco de pedra, então o centro do sprite é o centro da torre: girar o sprite
 * gira a torre em torno da célula e a animação não treme entre os quadros.
 *
 * discRatio    diâmetro do disco dividido pelo lado do sprite. Para o disco
 *              ocupar N pixels, o sprite é desenhado com lado N / discRatio --
 *              flecha, labareda, feixe e névoa passam de propósito um pouco
 *              para fora da célula.
 *
 * angleOffset  quanto girar além do ângulo de mira. O feixe do Altar e a
 *              labareda da Bombarda apontam para CIMA na arte, enquanto o
 *              ângulo 0 do jogo aponta para a direita.
 *
 * cycle        mapeia os três estados do tiro para índices de quadro:
 *              [sem atirar, acabou de atirar, recarregando]
 */

const SPRITES = {
  /* carregada com virote / corda solta / rearmada vazia */
  balista: {
    discRatio: 0.7743,
    angleOffset: 0,
    cycle: [0, 1, 2],
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  /* orbe carregado / feixe e arcos / orbe apagado */
  altar: {
    discRatio: 0.9034,
    angleOffset: Math.PI / 2,
    cycle: [0, 1, 2],
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  /* floco nitido / nevoa girando / floco palido */
  glacial: {
    discRatio: 0.8937,
    angleOffset: 0,
    cycle: [0, 1, 2],
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  /* canhao limpo / labareda / cano fumegando */
  bombarda: {
    discRatio: 0.9919,
    angleOffset: Math.PI / 2,
    cycle: [0, 1, 2],
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  }
};

/* Carrega tudo antes do primeiro quadro; até terminar, o desenho vetorial
 * antigo continua valendo, então nada pisca nem some. */
const SpriteSheet = {
  load() {
    for (const key of Object.keys(SPRITES)) {
      const set = SPRITES[key];
      set.images = set.frames.map(src => {
        const img = new Image();
        img.onload = () => { set.loaded = (set.loaded || 0) + 1; };
        img.src = src;
        return img;
      });
    }
  },

  /* Devolve o conjunto só quando TODOS os quadros chegaram: meio conjunto
   * carregado faria a torre alternar entre sprite e vetor. */
  get(key) {
    const set = SPRITES[key];
    return set && set.loaded === set.frames.length ? set : null;
  }
};
